(function(){"use strict";var _preloaderHidden=false;function hidePreloader(){if(_preloaderHidden)return;_preloaderHidden=true;var p=document.getElementById('preloader');if(p)p.classList.add('hidden');}
window.addEventListener('load',function(){setTimeout(hidePreloader,1800);});setTimeout(hidePreloader,3500);function showToast(message,type){type=type||'success';var container=document.querySelector('.toast-container');if(!container){container=document.createElement('div');container.className='toast-container';document.body.appendChild(container);}
var toast=document.createElement('div');toast.className='toast '+type;var iconSvg=type==='success'?'<svg viewBox="0 0 24 24"><path d="M22 11.08V12a10 10 0 11-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>':'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>';toast.innerHTML='<span class="toast-icon">'+iconSvg+'</span><span>'+(message||'')+'</span>';container.appendChild(toast);setTimeout(function(){toast.classList.add('show');},10);setTimeout(function(){toast.classList.remove('show');toast.addEventListener('transitionend',function(){if(toast.parentNode)toast.parentNode.removeChild(toast);});},4000);}
window.showSuccessToast=function(msg){showToast(msg,'success');};window.showErrorToast=function(msg){showToast(msg,'error');};function generateToken(){if(typeof crypto!=='undefined'&&crypto.randomUUID){try{return crypto.randomUUID();}catch(e){}}
return'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,function(c){var r=Math.random()*16|0,v=c=='x'?r:(r&0x3|0x8);return v.toString(16);});}
window.generateToken=generateToken;var dot=document.getElementById('cursorDot');var ring=document.getElementById('cursorRing');var mouseX=0,mouseY=0,ringX=0,ringY=0;var isMobile=window.matchMedia('(pointer:coarse)').matches;if(dot&&ring&&!isMobile){document.addEventListener('mousemove',function(e){mouseX=e.clientX;mouseY=e.clientY;dot.style.left=mouseX+'px';dot.style.top=mouseY+'px';});(function animRing(){ringX+=(mouseX-ringX)*0.12;ringY+=(mouseY-ringY)*0.12;ring.style.left=ringX+'px';ring.style.top=ringY+'px';requestAnimationFrame(animRing);})();}
var hamburger=document.getElementById('hamburger');var mobileMenu=document.getElementById('mobileMenu');var mobileClose=document.getElementById('mobileClose');var bodyEl=document.body;function openMobileMenu(){if(!mobileMenu||!hamburger)return;mobileMenu.classList.add('active');hamburger.classList.add('active');hamburger.setAttribute('aria-expanded','true');bodyEl.style.overflow='hidden';}
function closeMobileMenu(){if(!mobileMenu||!hamburger)return;mobileMenu.classList.remove('active');hamburger.classList.remove('active');hamburger.setAttribute('aria-expanded','false');bodyEl.style.overflow='';}
window.closeMobileMenu=closeMobileMenu;if(hamburger){hamburger.addEventListener('click',function(e){e.stopPropagation();if(mobileMenu&&mobileMenu.classList.contains('active'))closeMobileMenu();else openMobileMenu();});}
if(mobileClose)mobileClose.addEventListener('click',closeMobileMenu);document.addEventListener('keydown',function(e){if(e.key==='Escape')closeMobileMenu();});document.addEventListener('click',function(e){if(mobileMenu&&mobileMenu.classList.contains('active')&&!mobileMenu.contains(e.target)&&hamburger&&!hamburger.contains(e.target)){closeMobileMenu();}});var mobileLinks=mobileMenu?mobileMenu.querySelectorAll('a'):[];for(var i=0;i<mobileLinks.length;i++){mobileLinks[i].addEventListener('click',closeMobileMenu);}
var nav=document.getElementById('nav');if(nav){window.addEventListener('scroll',function(){nav.classList.toggle('scrolled',window.scrollY>60);},{passive:true});}
var revEls=document.querySelectorAll('.reveal');if('IntersectionObserver'in window){var ro=new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add('visible');ro.unobserve(e.target);}});},{threshold:0.1,rootMargin:'0px 0px -50px 0px'});revEls.forEach(function(el){ro.observe(el);});}else{for(var i=0;i<revEls.length;i++)revEls[i].classList.add('visible');}
var heroImg=document.querySelector('.hero-media img');if(heroImg&&!isMobile){window.addEventListener('scroll',function(){heroImg.style.transform='scale(1) translateY('+(window.scrollY*0.25)+'px)';},{passive:true});}
function updateCartBadge(){var token=localStorage.getItem('cart_token')||'';if(!token)return;fetch('/api/cart?token='+token,{headers:{'X-Cart-Token':token}}).then(function(r){return r.json();}).then(function(d){var items=(d.data&&d.data.cart&&d.data.cart.items)||[];var count=items.reduce(function(sum,i){return sum+(i.quantity||0);},0);var badge=document.getElementById('cart-badge');if(badge){badge.textContent=count>99?'99+':count;badge.classList.toggle('show',count>0);}}).catch(function(){});}
document.addEventListener('click',function(e){const btn=e.target.closest('.prod-act');if(!btn)return;const action=btn.getAttribute('data-action');const productId=btn.getAttribute('data-product-id');if(action==='addtocart'){const variantId=btn.getAttribute('data-variant-id')||'';const cartToken=localStorage.getItem('cart_token')||generateToken();localStorage.setItem('cart_token',cartToken);fetch('/api/cart/add',{method:'POST',headers:{'Content-Type':'application/json','X-Cart-Token':cartToken},body:JSON.stringify({product_id:productId,variant_id:variantId||null,quantity:1,token:cartToken})}).then(function(r){return r.json();}).then(function(d){if(d.success){updateCartBadge();showSuccessToast('Added to cart');}
else{showErrorToast(d.error||'Could not add to cart');}}).catch(function(){showErrorToast('Could not add to cart');});}
else if(action==='wishlist'){const wToken=localStorage.getItem('wishlist_token')||generateToken();localStorage.setItem('wishlist_token',wToken);fetch('/api/wishlist',{method:'POST',headers:{'Content-Type':'application/json','X-Cart-Token':wToken},body:JSON.stringify({product_id:productId,token:wToken})}).then(function(r){return r.json();}).then(function(d){if(d.success){showSuccessToast('Added to wishlist');}
else{showErrorToast(d.error||'Could not add to wishlist');}}).catch(function(){showErrorToast('Could not add to wishlist');});}});window.FV={token:localStorage.getItem('user_token')||'',user:null};try{window.FV.user=JSON.parse(localStorage.getItem('fv_user')||'null');}catch(e){}
function escHtml(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function renderNavAuth(){const area=document.getElementById('nav-auth-area');const mobileArea=document.getElementById('mobile-auth-area');if(!area)return;if(window.FV.user){const name=window.FV.user.first_name||window.FV.user.email.split('@')[0];area.innerHTML='<span class="nav-link-auth" id="nav-auth-trigger" tabindex="0" style="cursor:pointer">'+escHtml(name)+'</span>';if(mobileArea){mobileArea.innerHTML='<a href="/dashboard" class="btn-signin">Account</a>'+
'<button class="btn-register" onclick="logoutUser()">Logout</button>';}}else{area.innerHTML='<span class="nav-link-auth" id="nav-auth-trigger" tabindex="0" style="cursor:pointer">Sign In</span>';if(mobileArea){mobileArea.innerHTML='<a href="/login" class="btn-signin">Sign In</a>'+
'<a href="/register" class="btn-register">Register</a>';}}
wireAuthTrigger();}
function wireAuthTrigger(){const trigger=document.getElementById('nav-auth-trigger');if(!trigger)return;trigger.addEventListener('click',function(){if(window.FV.user)window.location.href='/dashboard';else window.location.href='/login';});trigger.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();trigger.click();}});}
window.logoutUser=function(){localStorage.removeItem('user_token');localStorage.removeItem('fv_user');window.FV.token='';window.FV.user=null;renderNavAuth();showSuccessToast('Signed out');};renderNavAuth();updateCartBadge();if(window.FV.token){fetch('/api/auth/me',{headers:{'Authorization':'Bearer '+window.FV.token}}).then(function(r){if(r.status===401){localStorage.removeItem('user_token');localStorage.removeItem('fv_user');window.FV.token='';window.FV.user=null;renderNavAuth();}else return r.json();}).then(function(d){if(d&&d.success){window.FV.user=d.data;localStorage.setItem('fv_user',JSON.stringify(d.data));renderNavAuth();}}).catch(function(){});}})();